import sqlite3

def update_translations():
    db_path = '/home/ibalamayaka_gmail_com/poetry_site/poetry.db'
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    translations = [
        ("自古以来云海苍茫，神仙居住的蓬莱仙岛和绛色宫阙不知在何处。人间自然有像赤城居士那样的人，如龙盘伏，如凤高飞。他清净无为，端坐忘却尘世，留下了八篇奇妙的文章。向东方玉霄望去，蓬莱仙境云雾缭绕，有云做车驾、风做马匹。游遍了天下九州四海，笑看世间纷繁如落花飞絮。在江边一见，如谪仙般的风采，无需言语便在心中赞许。精神遨游八方，浩然之气相对，酒酣之时席地而坐。等到《垂天》之赋写就，骑鲸飞升的道路平稳，约定好一起相伴而去。", 333551),
        ("楚山的修竹多如云，奇异的材质在千片树林中脱颖而出。龙须被剪去一半，凤胸微微隆起，玉般的肌肤均匀缠绕。淮南树叶飘落，云梦泽雨后初晴，明月当空微风吹拂。自从蔡中郎不见，桓伊离去之后，不知辜负了多少秋光。听说岭南的太守，后堂幽深，有娇小可人的绿珠。在雕花窗下学着吹奏，初次吹完《梁州》，《霓裳》还未结束。细品徵音，含着宫音，泛起商音，流淌羽音，一声直达云霄。为了给太守洗尽南方的蛮风瘴雨，吹奏出一曲清爽的秋日破晓之音。", 333552),
        ("像花又似非花，也无人怜惜任凭它坠落。离开枝头飘落路旁，细细思量却似无情又似有情。萦绕损耗了柔肠，困倦沉醉了娇眼，想睁开又闭上。梦中随风飘扬万里，去寻找情郎的去处，却又被黄莺的啼叫声惊醒。不恨这种花飞零落殆尽，只恨西园中落花难再缀上枝头。清晨雨过之后，遗踪何在？只有一池浮萍的碎影。春色如果有三分，两分化作了尘土，一分随着流水远去。细细看来，那不是点点杨花，那是离别之人的眼泪啊。", 333553),
        ("小船横渡春日的江水，躺在船上看翠绿的崖壁和红色的楼阁拔地而起。云端传来欢声笑语，是太守在举行盛大的宴会，佳人们已经半醉。高柱上弹奏着哀婉的琴弦，艳丽的歌声余音袅袅，绕着云朵萦绕在水面。想到老朋友年事已高，但风流韵致不减当年，独自回首在这烟波浩渺之中。推开枕头惘然若失看不见人影，只见空荡荡的江面上，明月照耀千里。听说五湖之中，你乘着小舟归去，依然携带着西子。云梦泽的南州，武昌的南岸，昔日的游历应该还记得。料想多情的你在梦里，特意来看我，也大概是这般情景。", 333554),
        ("归去吧，我该归向何处？相隔万里的家乡在岷山和峨眉山。人生大半辈子已经过去，未来的日子苦于不多。眼看着在黄州又度过了一个闰月，孩子们都满口楚地和吴地的方言了。山中的朋友，带着鸡豚和社酒，来劝慰我这老东坡。这又算得了什么？面对这离别，人生到底是为了什么，来来往往如同穿梭。且闲看着秋风中洛水的清波。堂前那细细的柳树正好，应该会想念我，不要剪去它柔嫩的枝条。还要传话给江南的父老乡亲，时常帮我晒一晒打渔的蓑衣。", 333555),
        ("香炉里香气缭绕，寒气生出冰冷的筷子，画堂里别有一番风光。主人情意深重，大摆宴席请出美丽的歌妓。细腻如玉的手搓揉着白皙的脖颈，嫩嫩的藕丝，刚刚织成仙女的衣裳。双双歌唱完毕，空旷的屋檐下月亮转移，余音依然悠扬。人间哪里有这样的景象？司空见惯，应该算是寻常。在座的有一位狂客，被撩拨得愁肠百结。报告说金钗掉落了，露出十指，如春笋般纤长。亲眼所见，完全胜过宋玉的描写，可以想象他作《高唐赋》时的情景。", 333556),
        ("蜗牛角一般微小的虚名，苍蝇头一样微薄的利润，算起来值得什么白白忙碌。事情都是前生注定的，谁弱又谁强？暂且趁着这清闲之身还未老去，尽情地让我放纵疏狂一番。百年的人生里，干脆就这么醉着，醉上三万六千场。细细思量。能有多少忧愁风雨，一半的时间都在互相妨碍。又何必拼死拼活地去说长道短。有幸面对这清风明月，把青苔当作草席铺展，把云彩当作帐幕高高挂起。江南真好，有千杯美酒，再听一曲《满庭芳》。", 333557),
        ("三十三年过去了，今天还有谁健在？算起来只有你和这滚滚长江了。凛然挺立的苍翠古柏，经受风霜的枝干世间难有匹敌。听说你在司州古县，在云溪之上的竹坞松窗间居住。江南的岸边，如果不是为了送你，我怎肯经过我的家乡。雨声淅沥。阵阵疏雨过后，风中的树林舞动，烟雾如盖，云彩如幢。希望能拿着这杯酒邀请你，一饮而尽。居士先生已经老了，真的是在梦里相对着残灯。歌舞已经停止，行人还没有起身，船上的鼓声已经砰砰敲响。", 333558),
        ("三十三年流落江湖，万里烟波一叶孤帆。故人们惊怪我为何青衫憔悴老态龙钟。我本疏狂另有异趣，你又为何奔波于尘世凡间？岁月流逝，困守穷途，船尾都冻连在了一起。山势陡峭。淮水对岸，高楼靠着翠壁，古寺掩映在空岩之中。我们携手在林间漫步，笑语欢声挽着衣袖。不要爬到孤峰的尽头，那会让望眼被云海迷乱。家乡在何处？顺着你的问话，我的归乡之梦萦绕在松树杉树之间。", 333559),
        ("落日余晖中卷起华丽的窗帘，亭子下的水面与天空相连。知道你为了我，新修了窗户，油漆的青红色还未干。常记得在平山堂上，倚着枕头看江南的烟雨，孤鸿在浩渺中消失。认得出醉翁的词句，山色在若有若无之中。一千顷的湖面，都像镜子一样平静，倒映着翠绿的山峰。忽然波浪卷起，掀动着如同白头翁般飘摇的一叶扁舟。可笑那兰台公子，不懂得庄子所说的天籁，偏要说风有雌雄。只要心中有一点浩然之气，便能乘着这千里的快哉之风。", 333560),
        ("谢安石在东海，做从事时已惊觉两鬓如秋。中年时亲友难舍难分，音乐也只能暂缓离别的哀愁。一旦功成名就，便准备从海路回到东方，扶病进入西州。高雅的志向被官冕所困，遗恨只能寄托在沧洲。岁末将至，必须早作打算，准备御寒的冬衣。故乡在千里之外，美好的地方总让人流连。我醉酒高歌时你来应和，醉倒了需要你来扶我，只有酒可以忘忧。任凭像刘备那样，相对着在高楼上高卧。", 333561),
        ("明月什么时候会出现呢？我端起酒杯询问青天。不知道天上的宫殿里，今天晚上是哪一年。我想乘着风回到天上，又害怕那用美玉建成的宫殿，高高在上让人经受不住寒冷。翩翩起舞把弄着清冷的影子，哪里比得上在人间呢。月亮转过朱红的阁楼，低低地照着雕花的窗户，照着没有睡意的人。月亮不应该有什么怨恨，为什么总是在人们离别的时候才圆呢？人有悲欢离合，月亮也有阴晴圆缺，这种事自古以来就难以两全。只希望人能够长长久久，即使相隔千里也能共同欣赏这美好的月色。", 333562),
        ("像儿女般亲昵地低语，夜里的灯火微微亮着。恩怨和交往都转瞬即逝，弹指之间泪水伴着叹息。忽然变成气宇轩昂的勇士，击鼓振奋士气，千里前行无人能阻。回首望去暮云遥远，飞絮在天空中搅动。在众多的鸟儿中，真正美丽的凤凰却独自不鸣。攀登时一步千险，跌落时却如同百丈般轻易。烦劳你指间的风雨之声，让我愁肠百结如水火交攻，起坐都难以平静。推开手还是归去吧，没有眼泪可以对你倾诉。", 333563),
        ("忧愁与喜悦交替而来，风雨过后，一江春水碧绿。巫峡的梦境，至今空余这群山如屏障般环绕。哪里比得上伯鸾带着德耀，虽然粗茶淡饭但也清欢十足。渐渐地光彩照耀着阶庭，生出兰玉般美好的子孙。在幽深的梦里，传递着心中的情曲。令人肠断的地方，任凭他去续写。文君的丈夫你知道吗？笑你曾经的卑微。你没看见周南人唱着汉广的歌吗？上天让夫子在乔木下歇息。便相伴着，左手抱着琴和书，在云端住宿。", 333564),
        ("江水和汉水从西边流来，高楼之下，水波如同深绿的葡萄。水中依然带着岷山峨眉山的云浪，以及锦江的春色。你是南山留下遗爱的地方官，我是剑门关外思念故乡的客子。面对这里的风物，难道没有深情，想要殷勤地诉说。江表的传记，你不要去读。那狂傲的处士，真的让人惋惜。空旷的沙洲对着鹦鹉，芦苇花在风中萧瑟。不只笑书生争论着什么事，曹操和黄祖都已飘忽而过。希望太守你能再写出像李白那样的诗，去追寻那黄鹤的踪迹。", 333565),
        ("东武的南城，新修的堤坝坚固，水波刚刚漫溢。隐隐约约遍布着广阔的树林和高高的土丘，红花卧在碧草之中。枝头上的残花已经被吹尽了，与你再向江边去寻找。试问前面的日子，还有多少春光？只剩三分之一。官场里的事情，什么时候才能忙完。风雨之外，没有多少安宁的日子。我们相伴着在曲水边泛舟，满城的人都争相出游。你没看见兰亭修禊的盛会吗，当时在座的都是豪迈超逸之人。到了如今，满山阴的修竹，只留下空空的陈迹。", 333566),
        ("清澈的颍水向东流去，愁苦的目光望断了在明灭中闪现的孤帆。做官游历的地方，青山白浪，有千重万叠。辜负了当年归隐林下的心愿，只能夜里对着床榻听着萧瑟的秋雨。只恨这一生，总是长久地处在离别之中，增添了许多白发。端起一杯酒，在黄河之畔。有无限的心事，从头细细诉说。互相看着仿佛还在昨天，却已经过去了许多年月。衣服上旧日的泪痕还留有苦涩，眉宇间的喜气又增添了几分神采。便和你一起，在池塘边寻找残存的春光，看那落花如雪。", 333567),
        ("老天难道没有感情吗？老天也懂得，多情地挽留客人。春天即将转暖，清晨为了什么事，还在飘洒着轻雪。你在春天到来时还系着官印的丝带，我却应该归隐去沉迷于泉石之中。只怕将来某个时候，端起酒杯忽然互相思念，却被云山阻隔。人世间的浮事，都难以预料。人纵然健康，头发也终将变白。何必推辞再醉一场，这样的欢乐难以寻觅。想要向佳人诉说离别的愁恨，泪珠却已经凝结在双睫上。只求不要让新燕飞回来的时候，音信断绝。", 333568),
        ("我梦见乘着小舟在太湖上漂浮。雪白的波浪摇动着天空，千顷白茫茫。醒来后满眼都是庐山，无数青色的崖壁倚天而立。这一生总是伴随着接淅而行。和你一样都是江南的客子。梦中游历，醒来后清雅地欣赏，如同飞梭般抛掷光阴。明天西风起时还要挂起船帆。唱着我的新词，泪水沾湿了胸襟。屈原离去后楚地的群山空寂，澧阳的兰芷也没有了颜色。你的才华就像刘禹锡一样。武陵更在遥远的西南。那《竹枝词》啊，不要摇动新唱的曲调，谁说古今是隔绝的呢。", 333569),
        ("大江向东奔流，波浪洗刷尽了千古以来的风流人物。那旧营垒的西边，人们说这就是三国时周瑜大破曹军的赤壁。乱石穿入高空，惊涛拍击着岸边，卷起千万堆如雪的浪花。江山美得像画一样，一时间涌现出多少英雄豪杰。遥想当年的周瑜，小乔刚刚嫁给他，他英姿勃发。手摇羽扇，头戴纶巾，在谈笑之间，强大的敌军便灰飞烟灭。我的思绪神游在当年的古战场，多情的人应该笑我，过早地生出了白发。人间就像一场梦，还是倒一杯酒来祭奠这江上的明月吧。", 333570),
        ("今年花开时节在幽深的院落里，整天刮着东风，吹散了煎茶的轻烟。只有绿苔芳草，柳絮如雪榆钱飘飞。听说城西那长廊古寺，是达官贵人的名园。有那带着酒意如同国色天香的牡丹，天生的香气染透了衣袖，为我留连忘返。清明节已经过去，残花已经无处寻觅，对着这景象在酒樽前洒下眼泪。秋天傍晚时分，那一枝为何，对我依然如故。高雅的宴会暂且追寻短暂的时光，凄清的秋风让人来不及欣赏残余的艳丽。不如留下这十分的春态，交付给明年的春天。", 333571),
        ("孤寂的客馆里灯光昏暗，荒野的客店外鸡声啼叫，旅途的枕头上残梦初醒。渐渐地月光如白练般收起，清晨的寒霜闪烁发光，云雾环绕的山峰像铺开的锦缎，早晨的露水清澈透明。世上的路漫长无尽，劳碌的生命却是有限的，像这样忙忙碌碌长久都难有欢笑。低声吟咏之后，默默地靠着马鞍，往事千头万绪涌上心头。当年一起在长安做客。就像陆机陆云两兄弟刚来时都是少年。笔下能写出千字的文章，胸中有万卷诗书，想要辅佐君王达到尧舜的盛世，这件事有什么难的。被任用或被废弃都由时势决定，出仕或隐退在于我自己，袖手旁观在闲处看看又何妨。只要身体长健，就优游度过岁月，姑且在酒杯前斗酒寻欢。", 333572),
        ("无情的流水送别了多情的客人。劝我喝酒就像曾经相识一样。酒杯传到手中不要推辞。这样的公道很难得。在曲水池上，用小字记下年月。还对着茂密的树林和高高的竹子，就像王羲之当年的永和节。纤细洁白的手像霜雪一样。笑着把秋天的花朵插在头上。在酒樽前不要怪歌声呜咽。又将是一场轻易的离别。这次离去后将高飞翱翔，赏遍那玉堂金阙。想问下次再来是哪一年，那时候应该已经有了白发。", 333573),
        ("今年春天来得早，腊月里就侵入了新年的气息。冰雪融化，春色初绽。东风带来了春的消息却无人看见，在柳树际、花朵边露出了微微的春意。寒夜虽然漫长，孤单的被子却容易暖和，钟鼓声渐渐清脆圆润。清晨初升的太阳半掩在山后。楼阁上笼罩着淡淡的烟雾。游人便开始计划去寻芳踏春，小桃和杏花，应该已经争相开放了。我衰老多病，少了许多情趣，疏散懒惰任由自己，只喜欢日上三竿了还在高卧安眠。", 333574),
        ("秋霜过后，已经失去了长淮的宽阔。只能空听着清澈的颍水潺潺流淌发出呜咽声。佳人还在唱着醉翁的词作，四十三年的光阴就像闪电般掠过。草头上的秋露像滚动的珍珠一样晶莹滑润。正是十五的盈盈月色，又仿佛回到了二八年华。与我一样都是认识醉翁的人，如今只有西湖波底的明月了。", 333575),
        ("知道你有神仙的骨格不怕寒暑。千年后的相逢也像在早晚之间。特意用离别的话语来惹恼佳人，就是为了看那梨花枝上带着雨滴的美丽模样。落花已经随着回旋的风飞去了。花本没有心机，是黄莺在自己诉说。明天早晨回去的路从池塘的西边下去，就再也看不见黄莺啼叫、花朵飘落的地方了。", 333576),
        ("三更时分梧桐叶上滴落着秋雨。惊醒了梦魂却无处寻觅。夜晚微凉的枕席已经让人感受到了秋意，更听见寒风中的蟋蟀在催促着织布机。梦中清清楚楚地记得来时的路。仿佛还在江边的亭子里醉饮歌舞。酒樽前必定有询问你的人，请告诉他们我离别后的心情和思绪。", 333577),
        ("公子们眼花缭乱头发纷乱，老夫的鼻子却先闻到了香气。衣巾飘落带来瑞香的风韵。惊醒了谪仙般的春梦。后土祠中那如玉般的花蕊，蓬莱殿后那牡丹的红艳。这花清雅绝俗更加娇嫩丰艳。端起酒杯，是什么让人心动。", 333578),
        ("小院里红色的栏杆弯弯曲曲，重重城墙里画鼓敲响了三通。再看那微弱的月光转动着清风。归去时那香气如云般入梦。翠绿的衣袖争相举起大酒杯，黑色的罗帕半插着斜红的花朵。灯花零落酒意正浓。绝妙的词语一时间飞扬闪动。", 333579),
        ("责怪这花枝带着哀怨哭泣，依托你的诗句名声远扬。凭借着草木记下了吴地的风俗。接着又写下了相如的云梦。挥笔时衣袖沾上了带着酒意的墨迹，诽谤花朵时脸上带着惭愧的红色。知道你却是为了情意深厚。怕见到这花儿惹人心动。", 333580),
        ("听说你带着双衔的凤带，不妨只穿一件单薄的鲛绡。夜里的香气知道是给谁烧的。怅惘地望着那沉水香的烟雾袅袅升起。云鬓在风前卷起绿意，如玉的容颜在醉意中泛起红潮。不要让这可爱的夜晚白白度过。月亮与佳人共同陪伴着你。", 333581),
        ("点点细雨落在楼头。重重江水外是平阔的湖面。当年在彭城举行戏马的盛会。今天却在这南浦感到凄凉。不要抱怨菊花还没有开放。暂且让红粉佳人互相搀扶。酒尽了不必去看那茱萸。俯仰之间体会人间古今的变迁。", 333582),
        ("龙焙是今年极品的茶，谷帘自古以来就是珍贵的泉水。双井的雪芽散发着神仙般的气息。它们的后代来自北苑。汤水沸腾，云状的茶沫浓郁雪白，茶盏中浮起花乳轻盈圆润。人间谁敢再去争奇斗艳。只去比试那红窗下的粉面佳人吧。", 333583),
        ("离别的梦境已经随着流水远去，眼泪依然沾湿了带着香气的泉水。司马相如依然是那清瘦的神仙。人在这瑶台阆苑之中。花雾在风中缥缈萦绕，歌声像水珠滴落般清脆圆润。蛾眉新画出了十分的娇艳。骑马归来时遮面的扇子。", 333584),
        ("世事就像一场大梦，人生能经历几度秋凉。夜里风吹树叶在走廊上作响。看看自己的眉头和鬓角。酒便宜的时候经常发愁客人少，月光明亮时多被云彩遮挡。中秋佳节谁能和我共赏这孤独的月光。端着酒杯凄然地向北望去。", 333585),
        ("不要叹息平原上的孤独落寞，且应对去鲁国时的迟缓。和你各自记得年轻的时候。必须相信人生就像寄居在这世上。白发千根送别你，深杯百罚也不要推辞。拍浮在水里何必把酒当作池水。我已经因为你的美德而沉醉了。", 333586),
        ("玉般的冰骨哪会发愁那瘴气毒雾，冰清玉洁的姿态自有仙风道骨。海上的仙人时常派来探访芳丛。倒挂着绿毛的么凤。白素的面容反而嫌弃粉脂的污浊，洗去妆容也不褪去嘴唇的红色。高雅的情趣已经追随着拂晓的云朵空去。不与那梨花做同样的梦。", 333587),
        ("清澈的水面泛着层层浅浅的波浪，横空的云层显得有些昏暗。马鞍下的挡泥板还没解开，白马依然骄傲。我想要醉眠在这芳草地里。可惜了这一条小溪的明月，不要让马蹄踏碎了这如玉的月光。解下马鞍靠着枕头在绿杨桥下。杜鹃的一声啼叫带来了春晓。", 333588),
        ("三次经过平山堂下，半生的岁月就在弹指一挥间。十年没有见到这位老仙翁了。墙壁上的书法如龙蛇飞动。想要凭吊这位文章太守，依然歌唱着杨柳春风。不要说万事转头皆空。还没有转头的时候这一切都是梦。", 333589),
        ("昨夜乘小舟在京口，今天早晨马头已经朝向长安。旧官有什么东西留给新官。只有这湖山的公案。这里的景色百年能有几次变迁，要在其中用词评价却是千难万难。太守的才气能够卷起波澜。与你一起把新诗来评断。", 333590),
        ("小巧的马儿从远方驮来两位侍女，青色的头巾、玉色的腰带和红色的靴子。溪山风景好的地方就安家。谁知道那是去巴峡的路，却看到了洛城的落花。花瓣旋转着飞舞如玉蕊，人间的春日刚刚偏斜。十年不见那紫云车。龙丘的新洞府里，铅鼎中正在炼着丹砂。", 333591),
        ("诗句端来磨砺我的迟钝，钝的锥子解不开锋芒。你的欢颜为我融化了冰霜。酒尽了清梦醒来，春草长满了池塘。应该惦念雪堂坡下的老农，当年我们一起采摘芸香。功成名就早早地还乡。调转车头来看望我，高大的乔木拥立着千百章。", 333592),
        ("我劝那大胡子张归去为好，从来都是自己忘记了情感。尘世的心消尽了，向道的心就平静了。江南和塞北，哪里不能去走走。俎豆庚桑真的已经过去了，凭借你对南荣的诉说。希望能听到吴越丰收的喜讯。君王如果有什么疑问，结袜还要依赖王生。", 333593),
        ("自古以来相随都不在办公的日子，何妨低声歌唱微微吟咏。天空垂下浓重的云层，春天的阴云密布。座位上的人已经半醉，帘外的雪将要下得更深。听说分司的狂放御史，紫云深处无路去追寻。凄风寒雨不断地袭来。问问囚徒长时间损耗着力气，看见鹤忽然惊动了心。", 333594),
        ("忘记成都来到这里已经十年，因为你未免又要思量。任凭清冷的泪水洒在江阳。知道故乡的山依然美好，孤单的客子独自感到悲凉。座位上的离愁你没有看见，归来时想要断肠却无肠可断。殷勤地再喝尽这杯离别的酒。这身躯就像那客舍，哪里才是我的故乡。", 333595),
        ("端着酒杯有谁在怀念李白，草堂遥遥指向江东。十里的珠帘卷起阵阵香风。花开了又谢，离别的愁恨有几千重。轻快的船只连夜渡江而来，一时间惊笑我这衰老的容颜。语音里依然带着吴地的软语。夜深人静对着酒杯的地方，依旧在梦魂之中。", 333596),
        ("九十天的春天都已经过去了，贪忙着去哪里追寻游玩。三分春色里有一分是忧愁。雨水打翻了榆荚的阵列，风儿转动着柳花的球。阆苑里的先生必须自我责备，蟠桃动辄就是千秋万岁。不知道人世间苦于厌倦索求。东皇太一也不去拘束，肯为太守留下来。", 333597),
        ("四大元素从来都是遍布各处的，这里的风水又有什么可疑的。本来就应该为我写出新诗。幽香的花朵开在山涧幽谷，寒冷的藻类在水波中舞动。借给卢仝两腋生风，天仙未必会互相思念。还凭着流水送人归去。层层山巅残留着落日，草上的露水已经沾湿了衣服。", 333598),
        ("一离开京城已经过了三次寒食节，在天涯走遍了红尘。依然用一笑来带来春天的温暖。没有波澜的真正古井，有节气的是秋天的竹子。惆怅着孤帆连夜出发，送行时只有淡月和微云。酒樽前不需要皱起眉头。人生就像一家旅馆，我也是其中的一个行人。", 333599),
        ("多病如沈约般消瘦，再也无法承受那腰间的金带。望湖楼上暗香飘来。和风在春天里拂动衣袖，明月之夜听见箫声。酒醒梦回，漏滴声长，隐隐约约的床榻上有着无尽的潮湿。美丽的佳人董娇饶已经不见了。在花上明月之间徘徊，空空度过这惹人怜爱的夜晚。", 333600)
    ]

    update_query = '''
        UPDATE poems 
        SET translation_baihua = ? 
        WHERE id = ?
    '''
    cursor.executemany(update_query, translations)
    conn.commit()
    conn.close()
    print(f"Updated {len(translations)} translations successfully.")

if __name__ == "__main__":
    update_translations()
